head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id, hexa) {
    var rgb = WebSquare.wUnit.getJq("#" + id).css("background-color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color == hexa;
    }
    return rgb == hexa;
}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#gridView1_cell_3_2', 'key-combo', {
			combo: 'down-arrow'
		});
	}
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#gridView1_cell_4_2', 'key-combo', {
			combo: 'up-arrow'
		});
	}		
	scwin.setSimulate3 = function() {
		scwin.simulateWrapper('#gridView1_cell_3_2', 'key-combo', {
			combo: 'left-arrow'
		});
	}
	scwin.setSimulate4 = function() {
		scwin.simulateWrapper('#gridView1_cell_3_1', 'key-combo', {
			combo: 'right-arrow'
		});
	}			
	scwin.setSimulate5 = function() {
		scwin.simulateWrapper('#gridView1_cell_3_1', 'key-combo', {
			combo: 'right-arrow'
		});
	}			

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_3_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

	WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
	WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('gridView1_cell_4_2', '#fca73c')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
	WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('gridView1_cell_3_2', '#fca73c')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
	WebSquare.wUnit.addCommand("pause", "500");	

    WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('gridView1_cell_3_1', '#fca73c')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
	WebSquare.wUnit.addCommand("pause", "500");	

	WebSquare.wUnit.addCommand("set", "scwin.setSimulate5()");
	WebSquare.wUnit.addCommand("pause", "500");	

    //WebSquare.wUnit.addCommand("assert", "scwin._checkRgb('gridView1_cell_3_3', '#fca73c')", "true");
    //WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

